INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('0cd4f3ad-b48d-596c-98b0-dbed9fc2bf6a','TEXT','The Paper Kite Map','Noah liked helping at the open oval, especially when there was a small job that nobody had planned. One Thursday, Noah noticed the kite map was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Noah decided to stop and look carefully instead of rushing.
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('ec69ac79-f154-5e6b-86a1-fa59fdf05571','TEXT','The Night Garden List — A Different Day','Ruby liked helping at the backyard habitat, especially when there was a small job that nobody had planned. One Friday, Ruby noticed the garden list was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Ruby decided to stop and look carefully instead of rushing.
