INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('71b81e64-85f2-5651-bc3c-e50f84535a78','TEXT','The Museum Window','Luca liked helping at the local museum, especially when there was a small job that nobody had planned. One Wednesday, Luca noticed the old window frame was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Luca decided to stop and look carefully instead of rushing.
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('78751989-2307-58c2-8363-a23ed6bda13c','TEXT','The Tiny Ferry — A Different Day','Zoe liked helping at the river workshop, especially when there was a small job that nobody had planned. One Wednesday, Zoe noticed the model ferry was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Zoe decided to stop and look carefully instead of rushing.
