INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('ee4c6988-2419-5ccb-b451-685ab5ba1ee4','TEXT','The Tiny Ferry','Zoe liked helping at the river workshop, especially when there was a small job that nobody had planned. One Wednesday, Zoe noticed the model ferry was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Zoe decided to stop and look carefully instead of rushing.
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('6c039e09-079a-5c46-a4f5-b3a2bba50c51','TEXT','The Bicycle Bell Project — A Different Day','Eli liked helping at the bike path, especially when there was a small job that nobody had planned. One Friday, Eli noticed the bicycle bell was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Eli decided to stop and look carefully instead of rushing.
