INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('7e5e325c-a7d5-53dc-94c9-e6283697c3c3','TEXT','The Repaired Book','Mia liked helping at the library corner, especially when there was a small job that nobody had planned. One Saturday, Mia noticed the repair kit was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Mia decided to stop and look carefully instead of rushing.
INSERT INTO stimuli (id,stimulus_type,title,content,asset_url,transcript,audio_duration_seconds,year_level,domain,status,created_by) VALUES ('76175678-b4a8-589c-bd51-ff5e10ea54a4','TEXT','The Windy Sculpture — A Different Day','Arun liked helping at the community hall, especially when there was a small job that nobody had planned. One Saturday, Arun noticed the reed sculpture was not working as expected. The problem seemed simple at first, but the usual quick fix did not help. Arun decided to stop and look carefully instead of rushing.
